          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The average effect should be modest and fairly stable across games; I do not expect strong asymmetry, so a normal prior is a clean approximation."
        },
        "parameters": {
          "mu": 0.25,
          "sigma": 0.1531,
          "conversion_note": "normal: sigma = (0.55 - (-0.05)) / 3.92 = 0.1531."
