          "interval_95_high": 0.46,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The effect is opponent-specific and can be larger than it looks when the defense is unprepared, so heavy tails are more honest than a tight symmetric guess."
