          "nu": 4,
          "mu": 0.11,
          "sigma": 0.1261,
          "conversion_note": "student_t with nu = 4, using t_{0.975,4} ≈ 2.776; sigma = (0.46 - (-0.24)) / (2 * 2.776) ≈ 0.1261."
        },
        "consistency_check": "Most plausible value is inside the interval, and the student_t family has support on all real numbers, so signed effects are allowed."
      }
    }
  ],
  "plot_script": "import numpy as np\nfrom scipy.stats import norm, t, skewnorm\nimport matplotlib.pyplot as plt\n\n# Edit this list to change the priors.\nstrategies = [\n    {'title': 'Aggressive fourth downs', 'family': 'normal', 'most_plausible': 0.25, 'params': {'mu': 0.25, 'sigma': 0.1531}},\n    {'title': 'First-down play-action', 'family': 'normal', 'most_plausible': 0.22, 'params': {'mu': 0.22, 'sigma': 0.1633}},\n    {'title': 'Two-high shells', 'family': 'normal', 'most_plausible': 0.18, 'params': {'mu': 0.18, 'sigma': 0.1429}},\n    {'title': 'Timeout to kill chaos', 'family': 'student_t', 'most_plausible': 0.0, 'params': {'nu': 4, 'mu': 0.0, 'sigma': 0.155}},\n    {'title': 'No-huddle bursts after explosives', 'family': 'student_t', 'most_plausible': 0.08, 'params': {'nu': 4, 'mu': 0.08, 'sigma': 0.137}},\n    {'title': 'Disguise-and-pressure mix', 'family': 'student_t', 'most_plausible': 0.11, 'params': {'nu': 4, 'mu': 0.11, 'sigma': 0.1261}},\n]\n\ndef make_dist(item):\n    fam = item['family']\n    p = item['params']\n    if fam == 'normal':\n        return norm(loc=p['mu'], scale=p['sigma'])\n    if fam == 'student_t':\n        return t(df=p['nu'], loc=p['mu'], scale=p['sigma'])\n    if fam == 'skew_normal':\n        return skewnorm(a=p['alpha'], loc=p['xi'], scale=p['omega'])\n    raise ValueError(f'Unknown family: {fam}')\n\nfig, axes = plt.subplots(2, 3, figsize=(16, 9))\naxes = axes.ravel()\n\nfor ax, item in zip(axes, strategies):\n    dist = make_dist(item)\n    lo = dist.ppf(0.001)\n    hi = dist.ppf(0.999)\n    xs = np.linspace(lo, hi, 800)\n    ys = dist.pdf(xs)\n    q025 = dist.ppf(0.025)\n    q975 = dist.ppf(0.975)\n\n    ax.plot(xs, ys, color='navy', lw=2)\n    ax.axvspan(q025, q975, color='skyblue', alpha=0.25, label='95% interval')\n    mp = item['most_plausible']\n    ax.axvline(mp, color='red', ls='--', lw=1.5, label='most plausible')\n    ax.plot([mp], [dist.pdf(mp)], 'ro')\n    ax.set_title(item['title'])\n    ax.set_xlabel('Change in own scoring margin (points)')\n    ax.set_ylabel('Density')\n    ax.grid(alpha=0.2)\n    ax.legend(fontsize=8)\n\n    print(item['title'], item['family'], item['params'])\n\nplt.tight_layout()\nplt.show()"
}
